import csv

def read_csv_dicts(path):
    rows = []
    with open(path, newline='', encoding='utf-8') as f:
        for row in csv.DictReader(f):
            converted = {}
            for key, value in row.items():
                try:
                    converted[key] = float(value) if '.' in value else int(value)
                except (ValueError, AttributeError):
                    converted[key] = value
            rows.append(converted)
    return rows

print(read_csv_dicts('sales.csv'))

def file_stats(path):
    lines = words = bytes_count = 0
    with open(path, 'rb') as f:
        for line in f:
            lines += 1
            bytes_count += len(line)
            words += len(line.split())
    return {'lines': lines, 'words': words, 'bytes': bytes_count}

print(file_stats('data.txt'))

