def human_filesize(num_bytes):
    units = ['B', 'KB', 'MB', 'GB', 'TB']
    size = float(num_bytes)
    for unit in units:
        if size < 1024 or unit == units[-1]:
            return f'{size:.1f} {unit}' if unit != 'B' else f'{int(size)} B'
        size /= 1024

print(human_filesize(1536000))

def dedupe_file(src, dst):
    seen, kept = set(), []
    with open(src, 'r', encoding='utf-8') as f:
        for line in f:
            if line not in seen:
                seen.add(line)
                kept.append(line)
    with open(dst, 'w', encoding='utf-8') as f:
        f.writelines(kept)
    return len(kept)

print(dedupe_file('raw.txt', 'clean.txt'))

import re

def search_file(path, pattern):
    results = []
    rx = re.compile(pattern)
    with open(path, 'r', encoding='utf-8') as f:
        for number, line in enumerate(f, 1):
            for match in rx.finditer(line):
                results.append((number, match.group(0)))
    return results

print(search_file('access.log', r'ERROR.*'))

import configparser

def read_config(path):
    parser = configparser.ConfigParser()
    if not parser.read(path):
        raise FileNotFoundError(path)
    parser.setdefault('core', {})
    parser['core'].setdefault('log_level', 'INFO')
    return {section: dict(parser[section]) for section in parser.sections()}

